/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - Vpotula
/// Service class for generating AMEX subsequent payment file.
/// </summary>
class METAMEXCustPaymSubsequentProposalService extends SysOperationServiceBase
{
    LedgerJournalTable  journalTable;
    Args args = new Args();

}

Method.Source:
    /// <summary>
    /// Runs business operation
    /// </summary>    
    public void runOperation()
    {
        try
        {
            this.initParameters();

            if (journalTable)
            {
                METAMEXCustSumForPaym::Main(args);
            }
            else
            {
                throw Error("@MET:AMEXJournalError");
            }

        }
        catch
        {
            info ("@MET:AMEXJobError");
        }
    }

    /// <summary>
    /// Initialise parameters required for generating payment file.
    /// </summary>
    private void initParameters()
    {
        journalTable = LedgerJournalTable::find(CustParameters::find().METAMEXPaymJournalNum);

        args.record(journalTable);
        args.parmEnumType(enumNum(UserInteractive));
        args.parmEnum(UserInteractive::No);

    }
